  '    Git receives the genuine checkout through __fspath__, never a synthetic repo.\n'
  '    """\n'
  "    def __init__(self, root, overrides, current_hashes, relative=Path('.'), *, fixture_layer=False):\n"
  '        self.root, self.overrides, self.current_hashes, self.relative = root, overrides, current_hashes, '
  'relative\n'
  '        self.fixture_layer = fixture_layer\n'
  '\n'
  '    def __truediv__(self, other):\n'
  '        relative = self.relative / other\n'
